//
//  GoldenZmanimTests.swift
//  KosherSwiftTests
//
//  Cross-checks KosherSwift against values generated by KosherJava itself (see tools/golden/GoldenGenerator.java): every
//  zman of ComprehensiveZmanimCalendar with the NOAA calculator (with the default settings and with elevation, half-day
//  chatzos and other settings changed), the core zmanim with the SPA, Meeus and SunTimes calculators, and the raw calculator
//  output (UTC rise / set hours at many zeniths, noon, midnight, solar elevation and azimuth, and the time at azimuth 90 / 270)
//  for 12 locations (both hemispheres, the equator, both sides of the date line, the Arctic, horizon elevations) on about 80
//  dates, including daylight saving transitions, solstices and dates from 1900 to 2099.
//

import Foundation
import XCTest
@testable import KosherSwift

final class GoldenZmanimTests: XCTestCase {

    /// The largest allowed difference between a KosherJava time and a KosherSwift time, in seconds (2 microseconds). A Swift
    /// `Date` is a `Double` of seconds since 2001, so around 2026 it resolves about a quarter of a microsecond, and the two
    /// runtimes' trigonometric functions can differ in the last bit.
    static let toleranceSeconds = 2e-6

    /// The largest allowed difference of raw calculator results (hours or degrees).
    static let toleranceRaw = 1e-9

    static let locations: [String: GeoLocation] = [
        "lakewood": GeoLocation(locationName: "lakewood", latitude: 40.0721087, longitude: -74.2400243, elevation: 15, timeZone: tz("America/New_York")),
        "woodcliff": GeoLocation(locationName: "woodcliff", latitude: 41.1181036, longitude: -74.0840691, elevation: 167, timeZone: tz("America/New_York")),
        "la": GeoLocation(locationName: "la", latitude: 34.0201613, longitude: -118.6919095, elevation: 71, timeZone: tz("America/Los_Angeles")),
        "jerusalem": GeoLocation(locationName: "jerusalem", latitude: 31.7962994, longitude: 35.1053185, elevation: 754, timeZone: tz("Asia/Jerusalem")),
        "norway": GeoLocation(locationName: "norway", latitude: 70.1498248, longitude: 9.1456867, elevation: 0, timeZone: tz("Europe/Oslo")),
        "sydney": GeoLocation(locationName: "sydney", latitude: -33.8688, longitude: 151.2093, elevation: 58, timeZone: tz("Australia/Sydney")),
        "macapa": GeoLocation(locationName: "macapa", latitude: 0.0349, longitude: -51.0694, elevation: 15, timeZone: tz("America/Belem")),
        "suva": GeoLocation(locationName: "suva", latitude: -18.1416, longitude: 178.4419, elevation: 6, timeZone: tz("Pacific/Fiji")),
        "ushuaia": GeoLocation(locationName: "ushuaia", latitude: -54.8019, longitude: -68.3030, elevation: 23, timeZone: tz("America/Argentina/Ushuaia")),
        "apia": GeoLocation(locationName: "apia", latitude: -13.8333, longitude: -171.75, elevation: 2, timeZone: tz("Pacific/Apia")),
        "horizon": GeoLocation(locationName: "horizon", latitude: 31.7683, longitude: 35.2137, elevation: 800, horizonElevationAtSunrise: 650,
                               horizonElevationAtSunset: 720, timeZone: tz("Asia/Jerusalem")),
        "utc": GeoLocation(locationName: "utc", latitude: 51.4772, longitude: 0, elevation: 0, timeZone: tz("UTC")),
    ]

    static func tz(_ identifier: String) -> TimeZone {
        return TimeZone(identifier: identifier)!
    }

    static func calculator(_ name: String) -> AstronomicalCalculator {
        switch name {
        case "SPA": return SPACalculator()
        case "Meeus": return MeeusCalculator()
        case "SunTimes": return SunTimesCalculator()
        default: return NOAACalculator()
        }
    }

    /// The lines of a gzipped file in the Golden folder next to this file.
    static func readLines(_ name: String) throws -> [Substring] {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("Golden").appendingPathComponent(name)
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
        process.arguments = ["gzip", "-dc", url.path]
        let pipe = Pipe()
        process.standardOutput = pipe
        try process.run()
        let data = pipe.fileHandleForReading.readDataToEndOfFile()
        process.waitUntilExit()
        XCTAssertEqual(process.terminationStatus, 0, "gzip failed for \(url.path)")
        return String(decoding: data, as: UTF8.self).split(separator: "\n")
    }

    static func localDate(_ text: Substring) -> LocalDate {
        let parts = text.split(separator: "-").map { Int($0)! }
        return LocalDate(year: parts[0], month: parts[1], day: parts[2])
    }

    /// The difference in seconds between a KosherJava "seconds.nanoseconds" value and a Swift value, computed without losing
    /// the nanoseconds to the precision of a Double holding the whole time.
    static func difference(_ java: Substring, _ swift: Double) -> Double {
        let parts = java.split(separator: ".")
        let seconds = Double(Int64(parts[0])!)
        let nanos = Double(Int64(parts[1])!) / 1_000_000_000
        // a negative value is written as -seconds.nanos with the nanos added to the (floored) seconds, like Instant
        return (swift - seconds) - nanos
    }

    func testAllZmanimMatchKosherJava() throws {
        var failures: [String] = []
        var zHeader: [Substring] = [], bHeader: [Substring] = []
        var compared = 0, maxDifference = 0.0
        var differences: [Double] = []
        for line in try GoldenZmanimTests.readLines("zmanim.tsv.gz") {
            let f = line.split(separator: "\t", omittingEmptySubsequences: false)
            if f[0] == "#Z" {
                zHeader = f
                continue
            }
            if f[0] == "#B" {
                bHeader = f
                continue
            }
            if f[0] != "Z" && f[0] != "B" {
                continue
            }
            let header = f[0] == "Z" ? zHeader : bHeader
            let geo = GoldenZmanimTests.locations[String(f[1])]!
            let czc = ComprehensiveZmanimCalendar(geoLocation: geo)
            czc.setAstronomicalCalculator(astronomicalCalculator: GoldenZmanimTests.calculator(String(f[3])))
            if f[4] == "1" {
                czc.setUseElevation(useElevation: true)
                czc.setUseAstronomicalChatzos(useAstronomicalChatzos: false)
                czc.setUseAstronomicalChatzosForOtherZmanim(useAstronomicalChatzosForOtherZmanim: true)
                czc.setCandleLightingOffset(candleLightingOffset: 40)
                czc.setAteretTorahSunsetOffset(ateretTorahSunsetOffset: 30)
            }
            czc.setLocalDate(localDate: GoldenZmanimTests.localDate(f[2]))
            var values: [String: ZmanimFormatter.Value] = [:]
            for (name, value) in czc.getFormattableValues() {
                values[name] = value
            }
            let row = "\(f[1]) \(f[2]) \(f[3]) config \(f[4])"
            for i in 5..<f.count {
                let name = String(header[i])
                var expected = f[i]
                guard let actual = values[name] else {
                    failures.append("\(name): not available in KosherSwift")
                    continue
                }
                if expected.hasPrefix("EX:UnsupportedOperationException") {
                    // KosherJava throws when the calculator (the SunTimesCalculator) can't calculate the solar elevation or
                    // azimuth the zman needs; KosherSwift returns nil
                    expected = "null"
                }
                if name == "getCandleLighting" && expected == "null" {
                    // KosherSwift returns plag hamincha when candle lighting would be before it (KosherJava returns null)
                    expected = f[header.firstIndex(of: "getPlagHaminchaGRA")!]
                }
                compared += 1
                switch actual {
                case .date(let date):
                    guard let date = date else {
                        if expected != "null" {
                            failures.append("\(row) \(name): expected \(expected), got nil")
                        }
                        continue
                    }
                    guard expected.hasPrefix("I") else {
                        failures.append("\(row) \(name): expected \(expected), got \(date)")
                        continue
                    }
                    let difference = abs(GoldenZmanimTests.difference(expected.dropFirst(), date.timeIntervalSince1970))
                    differences.append(difference)
                    maxDifference = max(maxDifference, difference)
                    if difference > GoldenZmanimTests.toleranceSeconds {
                        failures.append("\(row) \(name): expected \(expected), got \(date.timeIntervalSince1970) (\(difference) s)")
                    }
                case .duration(let duration):
                    guard let duration = duration else {
                        if expected != "null" {
                            failures.append("\(row) \(name): expected \(expected), got nil")
                        }
                        continue
                    }
                    guard expected.hasPrefix("D") else {
                        failures.append("\(row) \(name): expected \(expected), got \(duration)")
                        continue
                    }
                    let difference = abs(GoldenZmanimTests.difference(expected.dropFirst(), duration))
                    differences.append(difference)
                    maxDifference = max(maxDifference, difference)
                    if difference > GoldenZmanimTests.toleranceSeconds {
                        failures.append("\(row) \(name): expected \(expected), got \(duration) (\(difference) s)")
                    }
                }
            }
        }
        differences.sort()
        let median = differences.isEmpty ? 0 : differences[differences.count / 2]
        let exact = differences.filter { $0 < 0.5e-6 }.count
        print("Compared \(compared) zmanim with KosherJava: max difference \(maxDifference * 1e6) µs, median \(median * 1e9) ns, "
              + "\(exact) within half a microsecond, \(failures.count) failures")
        XCTAssertGreaterThan(compared, 400_000)
        XCTAssertTrue(failures.isEmpty, "\(failures.count) differences, for example:\n" + failures.prefix(40).joined(separator: "\n"))
    }

    func testCalculatorsMatchKosherJava() throws {
        let zeniths = [90, 90.833, 96, 102, 108, 106.1, 109.8, 98.5, 93.7, 84, 80]
        var failures: [String] = []
        var compared = 0
        var maxDifference = 0.0
        for line in try GoldenZmanimTests.readLines("zmanim.tsv.gz") {
            let f = line.split(separator: "\t", omittingEmptySubsequences: false)
            if f[0] != "C" {
                continue
            }
            let geo = GoldenZmanimTests.locations[String(f[1])]!
            let date = GoldenZmanimTests.localDate(f[2])
            let calculatorName = String(f[3])
            let c = GoldenZmanimTests.calculator(calculatorName)
            var actual: [Double] = []
            for z in zeniths {
                for adjust in [false, true] {
                    actual.append(c.getUTCSunrise(localDate: date, geoLocation: geo, zenith: z, adjustForElevation: adjust))
                    actual.append(c.getUTCSunset(localDate: date, geoLocation: geo, zenith: z, adjustForElevation: adjust))
                }
            }
            actual.append(c.getUTCNoon(localDate: date, geoLocation: geo))
            actual.append(c.getUTCMidnight(localDate: date, geoLocation: geo))
            if calculatorName != "SunTimes" {
                let noonish = date.startOfDayUTC.timeIntervalSince1970 + 12 * 3600 - Double(JavaMath.toLong(geo.getLongitude() * 240))
                for h in stride(from: -9, through: 9, by: 3) {
                    let at = Date(timeIntervalSince1970: noonish + Double(h * 3600 + 1234))
                    actual.append(c.getSolarElevation(date: at, geoLocation: geo))
                    actual.append(c.getSolarAzimuth(date: at, geoLocation: geo))
                }
                for azimuth in [90.0, 270.0] {
                    actual.append(c.getTimeAtAzimuth(localDate: date, geoLocation: geo, azimuth: azimuth))
                }
            }
            XCTAssertEqual(actual.count, f.count - 4, "column count for \(calculatorName)")
            for (i, value) in actual.enumerated() where i + 4 < f.count {
                let expected = Double(String(f[i + 4]))!
                compared += 1
                if expected.isNaN || value.isNaN {
                    if expected.isNaN != value.isNaN {
                        failures.append("\(f[1]) \(f[2]) \(calculatorName) column \(i): expected \(expected), got \(value)")
                    }
                    continue
                }
                var difference = abs(expected - value)
                if difference > 23.9 && difference < 24.1 {
                    difference = abs(difference - 24) // the same time on either side of 0:00 UTC
                } else if difference > 359.9 && difference < 360.1 {
                    difference = abs(difference - 360) // an azimuth on either side of north
                }
                maxDifference = max(maxDifference, difference)
                if difference > GoldenZmanimTests.toleranceRaw {
                    failures.append("\(f[1]) \(f[2]) \(calculatorName) column \(i): expected \(expected), got \(value) (\(difference))")
                }
            }
        }
        print("Compared \(compared) raw calculator values with KosherJava: max difference \(maxDifference), \(failures.count) failures")
        XCTAssertGreaterThan(compared, 30_000)
        XCTAssertTrue(failures.isEmpty, "\(failures.count) differences, for example:\n" + failures.prefix(40).joined(separator: "\n"))
    }
}
